@dataclass(frozen=True)
class Table:
    name: str
    columns: tuple[str, ...]
    path: Path

    def rows(self):
        with self.path.open(newline='') as source:
            reader = csv.reader(source)
            next(reader)
            for record in reader:
                yield tuple(value or None for value in record)

